load_counts <- function(path) {
  if (dir.exists(path)) {
    x <- Read10X(data.dir = path)
  } else if (grepl("\\.h5$", path, ignore.case = TRUE)) {
    x <- Read10X_h5(filename = path)
  } else if (grepl("\\.rds$", path, ignore.case = TRUE)) {
    x <- readRDS(path)
  } else if (grepl("\\.csv(\\.gz)?$", path, ignore.case = TRUE)) {
    x <- read.csv(path, row.names = 1, check.names = FALSE)
    x <- as(as.matrix(x), "dgCMatrix")
  } else if (grepl("\\.tsv(\\.gz)?$|\\.txt(\\.gz)?$", path, ignore.case = TRUE)) {
    x <- read.delim(path, row.names = 1, check.names = FALSE)
    x <- as(as.matrix(x), "dgCMatrix")
  } else {
    stop("Unsupported file type: ", path)
  }

  if (inherits(x, "Seurat")) {
    return(x)
  }

  if (is.list(x)) {
    if ("Gene Expression" %in% names(x)) {
      x <- x[["Gene Expression"]]
    } else {
      x <- x[[1]]
    }
  }

  x
}

