read_one <- function(f) {
  ext <- tolower(tools::file_ext(f))
  if (ext == "h5") {
    obj <- Read10X_h5(f)
    if (is.list(obj)) obj <- obj[[1]]
    return(obj)
  } else if (ext == "h5ad") {
    stop("h5ad import requires additional packages (e.g., SeuratDisk/reticulate).")
  } else if (ext == "rds") {
    return(readRDS(f))
  } else {
    stop("Unsupported file type: ", f)
