read_counts <- function(path) {
  if (dir.exists(path)) {
    files <- list.files(path, full.names = TRUE)
    if (any(grepl("\\.h5$", files, ignore.case = TRUE))) {
      h5file <- files[grepl("\\.h5$", files, ignore.case = TRUE)][1]
      return(Read10X_h5(h5file))
    }
    if (any(grepl("matrix\\.mtx(\\.gz)?$", files, ignore.case = TRUE))) {
      return(Read10X(path))
    }
    if (all(c("matrix.mtx", "barcodes.tsv", "features.tsv") %in% basename(files)) ||
        all(c("matrix.mtx.gz", "barcodes.tsv.gz", "features.tsv.gz") %in% basename(files)) ||
        all(c("matrix.mtx.gz", "barcodes.tsv", "features.tsv") %in% basename(files)) ||
        all(c("matrix.mtx", "barcodes.tsv.gz", "features.tsv.gz") %in% basename(files))) {
      return(Read10X(path))
    }
    csv_files <- files[grepl("\\.csv$|\\.csv\\.gz$", files, ignore.case = TRUE)]
    if (length(csv_files) > 0) {
      m <- read.csv(csv_files[1], row.names = 1, check.names = FALSE)
      return(as.matrix(m))
    }
    rds_files <- files[grepl("\\.rds$", files, ignore.case = TRUE)]
    if (length(rds_files) > 0) {
      return(readRDS(rds_files[1]))
    }
    stop("Unsupported input directory structure.")
  } else if (file.exists(path)) {
    if (grepl("\\.rds$", path, ignore.case = TRUE)) return(readRDS(path))
    if (grepl("\\.csv$|\\.csv\\.gz$", path, ignore.case = TRUE)) {
      m <- read.csv(path, row.names = 1, check.names = FALSE)
      return(as.matrix(m))
    }
    if (grepl("\\.h5$", path, ignore.case = TRUE)) return(Read10X_h5(path))
    stop("Unsupported input file format.")
  } else {
    stop("Input path does not exist.")
  }
}

